import sys


def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    a = [int(x) for x in data[1 : n + 1]]

    min_h = min(a)
    max_h = max(a)

    total_fases = 0

    for h in range(min_h, max_h):
        # Conta a quantidade de blocos contíguos de prédios com a_i <= h
        blocos = 0
        em_bloco = False
        for x in a:
            if x <= h:
                if not em_bloco:
                    blocos += 1
                    em_bloco = True
            else:
                em_bloco = False
        total_fases += blocos

    print(total_fases)


if __name__ == "__main__":
    solve()
